use std::io::{Read, Write};
use std::net::TcpListener;
use std::process::Command;
fn tool(name: &str) -> String {
    match Command::new(name).arg("--version").output() {
        Ok(o) => format!("success={} {}", o.status.success(), String::from_utf8_lossy(&o.stdout).trim()),
        Err(_) => "unavailable".to_owned(),
    }
}
fn main() {
    let port = std::env::var("PORT").unwrap_or_else(|_| "8080".to_owned());
    let listener = TcpListener::bind(format!("0.0.0.0:{port}")).unwrap();
    println!("QA_A692_RUST ready");
    for stream in listener.incoming() {
        if let Ok(mut s) = stream {
            let _ = s.read(&mut [0u8; 1024]);
            let body = format!("QA_A692_RUST\nrustc={}\nnode={}\nnpm={}\nyarn={}\npnpm={}\n", tool("rustc"), tool("node"), tool("npm"), tool("yarn"), tool("pnpm"));
            let response = format!("HTTP/1.1 200 OK\r\nContent-Type: text/plain; charset=utf-8\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{}", body.len(), body);
            let _ = s.write_all(response.as_bytes());
        }
    }
}

